typedef struct {
    int x;
    int id;
} HeapNode;

typedef struct {
    HeapNode *a;
    int sz, cap;
} MinHeap;

static void heap_init(MinHeap *h, int cap) {
    h->a = (HeapNode*)malloc(sizeof(HeapNode) * (cap + 5));
    h->sz = 0;
    h->cap = cap + 5;
}

static void heap_push(MinHeap *h, int x, int id) {
    int i = ++h->sz;
    while (i > 1 && h->a[i >> 1].x > x) {
        h->a[i] = h->a[i >> 1];
        i >>= 1;
    }
    h->a[i].x = x;
    h->a[i].id = id;
}

static HeapNode heap_pop(MinHeap *h) {
    HeapNode ret = h->a[1];
    HeapNode last = h->a[h->sz--];
    int i = 1;
    while ((i << 1) <= h->sz) {
        int c = i << 1;
        if (c + 1 <= h->sz && h->a[c + 1].x < h->a[c].x) c++;
        if (h->a[c].x >= last.x) break;
        h->a[i] = h->a[c];
        i = c;
    }
    h->a[i] = last;
    return ret;
}

static int heap_empty(MinHeap *h) {
    return h->sz == 0;
}

typedef struct {
    int *to, *next, *eid;
    int ecnt;
    int n;
    int *head;
} Graph;

static void graph_init(Graph *g, int n, int m) {
    g->n = n;
    g->head = (int*)malloc(sizeof(int) * (n + 1));
    for (int i = 1; i <= n; i++) g->head[i] = -1;
    g->to = (int*)malloc(sizeof(int) * (2 * m));
    g->next = (int*)malloc(sizeof(int) * (2 * m));
    g->eid = (int*)malloc(sizeof(int) * (2 * m));
    g->ecnt = 0;
}

static void graph_add_edge(Graph *g, int u, int v, int id) {
    g->to[g->ecnt] = v;
    g->eid[g->ecnt] = id;
    g->next[g->ecnt] = g->head[u];
    g->head[u] = g->ecnt++;
}

static int cmp_edge(const void *a, const void *b) {
    const Edge *x = (const Edge*)a;
    const Edge *y = (const Edge*)b;
    if (x->w < y->w) return -1;
    if (x->w > y->w) return 1;
    return 0;
}

