        a = find(a); b = find(b);
        if (a == b) return false;
        if (sz[a] < sz[b]) swap(a, b);
        p[b] = a;
        sz[a] += sz[b];
        sum[a] += sum[b];
        return true;
    }
    long long compSum(int x) {
        return sum[find(x)];
    }
};

