class DSU:
    def __init__(self, n, weights):
        self.parent = list(range(n))
        self.total_weight = weights[:]  # sum of vertex weights in component

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return False
        if self.total_weight[rx] < self.total_weight[ry]:
            rx, ry = ry, rx
        self.parent[ry] = rx
        self.total_weight[rx] += self.total_weight[ry]
        return True

def solve():
    input_data = sys.stdin.read().strip().split()
    n, m = int(input_data[0]), int(input_data[1])
    weights = list(map(int, input_data[2:2+n]))

    edges = []
    idx = 2 + n
    for _ in range(m):
        a, b, y = int(input_data[idx])-1, int(input_data[idx+1])-1, int(input_data[idx+2])
        idx += 3
        edges.append((y, a, b))

    # Sort edges descending by weight
    edges.sort(reverse=True)

    dsu = DSU(n, weights)
    removed = 0

    for y, a, b in edges:
        ra, rb = dsu.find(a), dsu.find(b)
        if ra == rb:
            # Already in same component, must check if edge is valid
            if dsu.total_weight[ra] < y:
                removed += 1
        else:
            total = dsu.total_weight[ra] + dsu.total_weight[rb]
            if total < y:
                removed += 1
            else:
                dsu.union(a, b)

    print(removed)

