        edges.append((a,b,y)); idx+=3

    def get_components(edge_mask):
        parent = list(range(N))
        def find(x):
            while parent[x]!=x: parent[x]=parent[parent[x]]; x=parent[x]
            return x
        def union(x,y):
            px,py=find(x),find(y)
            if px!=py: parent[px]=py
        for i in range(M):
            if edge_mask>>i&1: union(edges[i][0],edges[i][1])
        comp={}
        for v in range(N):
            r=find(v); comp.setdefault(r,[]).append(v)
        return comp

    from functools import lru_cache
    @lru_cache(maxsize=None)
    def min_remove(mask):
        comp = get_components(mask)
        comp_sum = {}
        for r,vs in comp.items(): comp_sum[r]=sum(X[v] for v in vs)
        parent=[list(range(N))]
        # find violating edge
        uf=list(range(N))
        def find(x):
            while uf[x]!=x: uf[x]=uf[uf[x]]; x=uf[x]
            return x
        for i in range(M):
            if mask>>i&1:
                a,b,y=edges[i]
                r=find(a)
                if comp_sum[r]<y:
                    # must remove some edge; try removing each edge in this component
                    best=M
                    for j in range(M):
                        if mask>>j&1:
                            a2,b2,_=edges[j]
                            if find(a2)==r or find(b2)==r:
                                best=min(best,1+min_remove(mask^(1<<j)))
                    return best
        return 0

